/**
 * US ZIP code -> county, for every state.
 *
 * Generated by scripts/generateUsZipCounty.js from the US Census Bureau
 * ZCTA-to-county relationship files. Regenerate rather than editing the JSON
 * by hand -- a wrong pair routes a patient's emergency to the wrong nurses.
 *
 * Counties are identified by their 5-digit FIPS code, never by name: names
 * like "Washington" repeat across some 30 states.
 */

const usCounties = require('./data/usCounties.json');
const usZipCounty = require('./data/usZipCounty.json');

/** Number of leading digits that identify a ZIP; HHAeXchange may send ZIP+4. */
const ZIP5_LENGTH = 5;

const COUNTY_FIPS_LENGTH = 5;

/** ZIP5 -> county FIPS. Straddling ZIPs with no dominant county are omitted. */
const US_ZIP_TO_COUNTY_FIPS = Object.freeze(usZipCounty);

/** County FIPS -> [stateCode, name]. */
const US_COUNTIES = Object.freeze(usCounties);

const US_COUNTY_STATE_INDEX = 0;
const US_COUNTY_NAME_INDEX = 1;

module.exports = {
  ZIP5_LENGTH,
  COUNTY_FIPS_LENGTH,
  US_ZIP_TO_COUNTY_FIPS,
  US_COUNTIES,
  US_COUNTY_STATE_INDEX,
  US_COUNTY_NAME_INDEX,
};
